import{_ as o,r as s,o as p,c as l,e as n,a as c,s as r}from"./chunks/framework.CXcwiNg-.js";const v=JSON.parse('{"title":"Поле Color Picker - October CMS - 3.x","titleTemplate":false,"description":"Виджет формы","frontmatter":{"subtitle":"Виджет формы","shortname":"Color Picker"},"headers":[{"level":2,"title":"Динамические доступные цвета","slug":"динамические-доступные-цвета","link":"#динамические-доступные-цвета","children":[]}],"relativePath":"3.x/ru/element/form/widget-colorpicker.md","filePath":"3.x/ru/element/form/widget-colorpicker.md"}'),u={name:"3.x/ru/element/form/widget-colorpicker.md"};function i(d,a,k,g,m,y){const t=s("pre-heading"),e=s("post-heading");return p(),l("div",null,[n(t),a[0]||(a[0]=c("h1",null,"Поле Color Picker",-1)),n(e),a[1]||(a[1]=r(`<p><code>colorpicker</code> — рендерит элементы управления для выбора шестнадцатеричного значения цвета.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">color</span><span class="token punctuation">:</span>
    <span class="token key atrule">label</span><span class="token punctuation">:</span> Background
    <span class="token key atrule">type</span><span class="token punctuation">:</span> colorpicker
</code></pre></div><p>Поддерживаются и обычно используются следующие <a href="./../form-fields.html">свойства поля</a>.</p><div class="table"><table tabindex="0"><thead><tr><th>Свойство</th><th>Описание</th></tr></thead><tbody><tr><td><strong>label</strong></td><td>имя при отображении поля формы пользователю.</td></tr><tr><td><strong>default</strong></td><td>значение по умолчанию (строка), необязательно.</td></tr><tr><td><strong>comment</strong></td><td>пояснительный комментарий под полем.</td></tr><tr><td><strong>availableColors</strong></td><td>список доступных цветов в виде массива.</td></tr><tr><td><strong>allowEmpty</strong></td><td>разрешает пустое значение. По умолчанию: <code>false</code></td></tr><tr><td><strong>allowCustom</strong></td><td>разрешает выбор произвольного цвета. По умолчанию: <code>true</code></td></tr><tr><td><strong>showAlpha</strong></td><td>отображает ползунок прозрачности и устанавливает 8-значный hex-код. По умолчанию: <code>false</code></td></tr><tr><td><strong>showInput</strong></td><td>отображает текстовое поле ввода рядом с палитрой и отключает доступные цвета. По умолчанию: <code>false</code></td></tr></tbody></table></div><p>Вы можете определить предустановленные цвета, задав свойство <code>availableColors</code> как массив hex-цветов. Свойство <code>allowCustom</code> может использоваться для отключения выбора произвольного цвета, и оно необязательно.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">color</span><span class="token punctuation">:</span>
    <span class="token key atrule">label</span><span class="token punctuation">:</span> Background
    <span class="token key atrule">type</span><span class="token punctuation">:</span> colorpicker
    <span class="token key atrule">availableColors</span><span class="token punctuation">:</span> <span class="token punctuation">[</span><span class="token string">&#39;#000000&#39;</span><span class="token punctuation">,</span> <span class="token string">&#39;#111111&#39;</span><span class="token punctuation">,</span> <span class="token string">&#39;#222222&#39;</span><span class="token punctuation">]</span>
    <span class="token key atrule">allowCustom</span><span class="token punctuation">:</span> <span class="token boolean important">false</span>
</code></pre></div><div class="custom-block tip"><p>Если поле <code>availableColors</code> не определено в YAML-файле, палитра использует набор из 20 цветов по умолчанию.</p></div><p>Используйте свойство <code>showAlpha</code> для включения прозрачности в выбор цвета — это создаёт 8-значное hex-значение.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">color</span><span class="token punctuation">:</span>
    <span class="token key atrule">label</span><span class="token punctuation">:</span> Background
    <span class="token key atrule">type</span><span class="token punctuation">:</span> colorpicker
    <span class="token key atrule">showAlpha</span><span class="token punctuation">:</span> <span class="token boolean important">true</span>
</code></pre></div><p>Используйте свойство <code>showInput</code> для отображения текстового поля ввода рядом с цветом. В этом режиме доступные цвета отключаются, а выбор и ввод произвольного hex-цвета становятся основной задачей.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">color</span><span class="token punctuation">:</span>
    <span class="token key atrule">label</span><span class="token punctuation">:</span> Primary Color
    <span class="token key atrule">type</span><span class="token punctuation">:</span> colorpicker
    <span class="token key atrule">showInput</span><span class="token punctuation">:</span> <span class="token boolean important">true</span>
</code></pre></div><h2 id="динамические-доступные-цвета"><a href="#динамические-доступные-цвета" class="header-anchor">#</a> Динамические доступные цвета</h2><p>Доступные цвета могут быть получены из класса модели, если задать <code>availableColors</code> как имя метода, объявленного в классе модели. Этот метод должен возвращать массив hex-цветов в том же формате, что и в примере выше. Первый аргумент метода — имя поля, второй — текущее значение поля, третий — текущий объект данных всей формы.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">color</span><span class="token punctuation">:</span>
    <span class="token key atrule">label</span><span class="token punctuation">:</span> Background
    <span class="token key atrule">type</span><span class="token punctuation">:</span> colorpicker
    <span class="token key atrule">availableColors</span><span class="token punctuation">:</span> myColorList
</code></pre></div><p>Предоставление доступных цветов в классе модели:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">myColorList</span><span class="token punctuation">(</span><span class="token variable">$fieldName</span><span class="token punctuation">,</span> <span class="token variable">$value</span><span class="token punctuation">,</span> <span class="token variable">$formData</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token keyword">return</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;#000000&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;#111111&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;#222222&#39;</span><span class="token punctuation">]</span>
<span class="token punctuation">}</span>
</code></pre></div>`,16))])}const b=o(u,[["render",i]]);export{v as __pageData,b as default};
